import type { MetadataRoute } from "next";
import manifest from "@/lib/sitemap-manifest.json";

// Generated by scripts/stamp-lastmod.mjs (runs on predev/prebuild).
// It lists every page with its path, primary image and `lastmod`, which only
// changes when that page's content (or a component it imports) changes.

const SITE_URL = (
  process.env.SITE_URL ?? "https://alzayedmoversuae.com"
).replace(/\/$/, "");

type Group = "root" | "locations" | "services" | "company";

const RULES: Record<
  Group,
  {
    priority: number;
    changeFrequency: MetadataRoute.Sitemap[number]["changeFrequency"];
  }
> = {
  root: { priority: 1, changeFrequency: "monthly" }, // home
  locations: { priority: 0.9, changeFrequency: "monthly" },
  company: { priority: 0.8, changeFrequency: "yearly" }, // about + contact
  services: { priority: 0.7, changeFrequency: "monthly" },
};

export default function sitemap(): MetadataRoute.Sitemap {
  return manifest.map((page) => {
    const rule = RULES[page.group as Group];
    return {
      url: page.path === "/" ? `${SITE_URL}/` : `${SITE_URL}${page.path}`,
      lastModified: page.lastmod, // "YYYY-MM-DD"
      changeFrequency: rule.changeFrequency,
      priority: rule.priority,
      images: [`${SITE_URL}${encodeURI(page.image)}`],
    };
  });
}
